Sure, I'd be happy to help you with that! Here's a Python program that simulates a shopping cart using a list to store items. The program allows the user to add, remove, and view items using if/else statements.

```python
shopping_cart = []

def add_item(item):
    """Add an item to the shopping cart."""
    if item.lower() not in ['add', 'a', 'i', 'm']:
        print("Invalid input. Please use 'add' or 'a' to add an item.")
        return

    if item.lower() == 'add':
        shopping_cart.append('')  # Add an empty string to represent an item
        print(f"You have added an item to your cart.")
    else:
        shopping_cart.append(item)
        print(f"You have added '{item}' to your cart.")

def remove_item(index):
    """Remove an item from the shopping cart at a given index."""
    if index < 0 or index >= len(shopping_cart):
        print("Invalid index. Please enter a valid index between 0 and the length of the cart.")
        return

    shopping_cart.pop(index)
    print(f"You have removed the item at index {index} from your cart.")

def view_cart():
    """Print the items in the shopping cart."""
    if not shopping_cart:
        print("Your cart is currently empty.")
        return

    print("Your cart contains:")
    for i, item in enumerate(shopping_cart, start=1):
        print(f"{i}. {item}")

def main():
    while True:
        print("\nShopping cart simulator:")
        print("1. Add an item")
        print("2. Remove an item")
        print("3. View cart")
        print("4. Exit")

        action = input("Enter your choice: ").strip().lower()

        if action == '1':
            item = input("Enter the item to add: ").strip()
            add_item(item)

        elif action == '2':
            index = int(input("Enter the index to remove an item (0-based): "))
            remove_item(index)

        elif action == '3':
            view_cart()

        elif action == '4':
            print("Exiting the shopping cart simulator...")
            break

        else:
            print("Invalid input. Please enter a valid choice between 1 and 4.")

if __name__ == "__main__":
    main()
```

This program will allow the user to add, remove, and view items in their shopping cart. You can customize the error messages and the way items are represented in the cart as needed.
